// Audit captures this operation's existing stored changes without getters, mutators or additional database work.
// Updates, soft deletes and restorations record assigned or changed fields plus the key; create and delete record every field.
// Standalone Compare results have no captured operation and cannot become lifecycle audit records.
func (changes ProjectChanges) Audit(policy ProjectAuditPolicy) (record.Model[Project, model.ID[Project]], error) {
	operation, present := changes.operation.Get()
	if !present {
		return record.Model[Project, model.ID[Project]]{}, foundryfault.New(foundryfault.Missing, "audit requires captured model changes")
	}
	item, present := changes.after.Get()
	if !present {
		item, present = changes.before.Get()
	}
	if !present {
		return record.Model[Project, model.ID[Project]]{}, foundryfault.New(foundryfault.Missing, "audit requires a stored model snapshot")
	}
	builder, err := record.NewBuilder(item.FoundryReference(), operation, "id", policy.ID)
	if err != nil {
		return record.Model[Project, model.ID[Project]]{}, err
	}
	if err = record.Capture(builder, "id", codec.ID[Project](), changes.fields.ID, policy.ID); err != nil {
		return record.Model[Project, model.ID[Project]]{}, err
	}
	if err = record.Capture(builder, "team_id", codec.ID[Team](), changes.fields.TeamID, policy.TeamID); err != nil {
		return record.Model[Project, model.ID[Project]]{}, err
	}
	if err = record.Capture(builder, "slug", codec.String[Slug](), changes.fields.Slug, policy.Slug); err != nil {
		return record.Model[Project, model.ID[Project]]{}, err
	}
	if err = record.Capture(builder, "enabled", codec.Bool[bool](), changes.fields.Enabled, policy.Enabled); err != nil {
		return record.Model[Project, model.ID[Project]]{}, err
	}
	if err = record.Capture(builder, "deleted_at", codec.Nullable(codec.Time()), changes.fields.DeletedAt, policy.DeletedAt); err != nil {
		return record.Model[Project, model.ID[Project]]{}, err
	}
	return builder.Build()
}

