// ProjectAuditing declares automatic auditing for normal lifecycle writes. Register it once through audit.Register.
// Existing observer registration owns dependency construction, duplicate detection and transaction lifetime.
func ProjectAuditing(policy ProjectAuditPolicy) record.Declaration {
	return record.Declare(func(registrar *foundation.Registrar, pool foundation.Key[*database.DB], resolve record.ResolveWriter) error {
		name, err := record.ObserverName[Project]()
		if err != nil {
			return err
		}
		return RegisterProjectObserver(registrar, pool, NewProjectObserver(name), func(resolver foundation.Resolver) (func() ProjectHooks, error) {
			writer, err := resolve(resolver)
			if err != nil {
				return nil, err
			}
			if writer == nil {
				return nil, foundryfault.New(foundryfault.Invalid, "audit writer is not initialized")
			}
			return func() ProjectHooks {
				write := func(ctx context.Context, tx *database.Tx, changes ProjectChanges) error {
					captured, err := changes.Audit(policy)
					if err != nil {
						return err
					}
					return writer.RecordModel(ctx, tx, captured.Entry())
				}
				return ProjectHooks{Created: write, Updated: write, Deleted: write, Restored: write}
			}, nil
		})
	})
}
